async function loadAds(){const box=$('adRows');if(!box||currentRole!=='admin')return;const {data,error}=await db.from('ad_campaigns').select('*').order('created_at',{ascending:false}).limit(300);if(error){box.innerHTML='<tr><td colspan="6">'+esc(error.message)+'</td></tr>';return}const p={header:'হেডার',top:'হোমপেজ ব্যানার',important_links:'গুরুত্বপূর্ণ লিংকের উপরে',side:'সাইডবার',side_tall:'সাইডবারের নিচে (লম্বা বিজ্ঞাপন)',feed:'পুরনো সংবাদ পাশে (ফিড)',bottom:'ফুটার ব্যানার',article:'নির্দিষ্ট সংবাদ'},s={draft:'খসড়া',active:'চালু',paused:'স্থগিত',expired:'মেয়াদ শেষ'},pay={unpaid:'বাকি',partial:'আংশিক',paid:'পরিশোধিত'};box.innerHTML=(data||[]).map(a=>'<tr><td><b>'+esc(a.advertiser_name)+'</b><br>'+esc(a.title)+'<br><small>'+(a.ad_type==='network'?'নেটওয়ার্ক':'নিজস্ব')+'</small></td><td>'+(String(a.placement||'').split(',').map(v=>p[v]||v).join(', '))+'</td><td>'+adDate(a.start_at)+'<br>শেষ: '+adDate(a.end_at)+'</td><td>'+Number(a.price||0).toLocaleString('bn-BD')+' টাকা<br>'+(pay[a.payment_status]||a.payment_status)+'</td><td>'+(s[a.status]||a.status)+'</td><td><button class="btn" data-ad-edit="'+a.id+'">সম্পাদনা</button> <button class="btn btn-light" data-ad-toggle="'+a.id+'">'+(a.status==='active'?'স্থগিত':'চালু')+'</button> <button class="btn btn-red" data-ad-delete="'+a.id+'">মুছুন</button></td></tr>').join('')||'<tr><td colspan="6">এখনো কোনো বিজ্ঞাপন নেই।</td></tr>';box.querySelectorAll('[data-ad-edit]').forEach(b=>b.onclick=()=>editAd(data.find(a=>String(a.id)===b.dataset.adEdit)));box.querySelectorAll('[data-ad-toggle]').forEach(b=>b.onclick=async()=>{const a=data.find(x=>String(x.id)===b.dataset.adToggle);const {error}=await db.from('ad_campaigns').update({status:a.status==='active'?'paused':'active'}).eq('id',a.id);if(error)toast(error.message);else loadAds()});box.querySelectorAll('[data-ad-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('বিজ্ঞাপন মুছবেন?'))return;const {error}=await db.from('ad_campaigns').delete().eq('id',b.dataset.adDelete);if(error)toast(error.message);else loadAds()});await loadAdInventory()}
function editAd(a){$('adId').value=a.id;$('adAdvertiser').value=a.advertiser_name;$('adTitle').value=a.title;$('adType').value=a.ad_type||'direct';const selected=String(a.placement||'').split(',');$('adPlacementSelect').value=selected[0]||'header';document.querySelectorAll('input[name="adPlacement"]').forEach(x=>x.checked=selected.includes(x.value));updateAdSizeHint();$('adImage').value=a.image_url||'';$('adImageFile').value='';$('adVideoFile').value='';$('adVideoPreview').classList.add('hidden');if(a.image_url&&/\.(mp4|webm|ogg)(\?.*)?$/i.test(a.image_url)){$('adVideoPreview').src=a.image_url;$('adVideoPreview').classList.remove('hidden');$('adImagePreview').classList.add('hidden')}else if(a.image_url){$('adImagePreview').src=a.image_url;$('adImagePreview').classList.remove('hidden')}else $('adImagePreview').classList.add('hidden');$('adTarget').value=a.target_url||'';let motion={};try{motion=JSON.parse(a.embed_code||'{}')}catch{};$('adAnimation').checked=!!motion.animation;$('adAnimationType').value=motion.animation_type||'fade';$('adSlider').checked=!!motion.slider;$('adSliderInterval').value=String(motion.slider_interval||5000);$('adEmbed').value='';if($('adNetworkCode')){try{const raw=JSON.parse(a.embed_code||'{}');$('adNetworkCode').value=raw.network_code||''}catch{$('adNetworkCode').value=a.ad_type==='network'?(a.embed_code||''):''}}const dt=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';$('adStart').value=dt(a.start_at);$('adEnd').value=dt(a.end_at);$('adPrice').value=a.price||0;$('adPayment').value=a.payment_status;$('adStatus').value=a.status;$('adEnabled').checked=a.status==='active';$('adArticle').value=a.article_id||'';$('adNetworkCode').dispatchEvent(new Event('input'));updateAdLiveStatus();document.querySelector('[data-tab="ads"]').click()}
$('adReset')?.addEventListener('click',resetAd);$('refreshAds')?.addEventListener('click',loadAds);
$('adForm')?.addEventListener('submit',async e=>{e.preventDefault();if(currentRole!=='admin')return;try{const id=$('adId').value,adType=$('adType').value;let adImage=$('adImage').value.trim();const adFile=$('adImageFile')?.files[0],adVideo=$('adVideoFile')?.files[0];if(adFile&&adVideo)throw new Error('ছবি অথবা ভিডিও—একটি মিডিয়া নির্বাচন করুন।');if(adFile)adImage=await uploadImage(adFile,'ads');if(adVideo)adImage=await uploadVideo(adVideo,'ads');const placements=[...document.querySelectorAll('input[name="adPlacement"]:checked')].map(x=>x.value);if(!placements.length)throw new Error('বিজ্ঞাপনের অবস্থান নির্বাচন করুন।');$('adEnabled').checked=$('adStatus').value==='active';if(placements.includes('article')&&placements.length>1)throw new Error('নির্দিষ্ট সংবাদ বিজ্ঞাপন একক স্থানেই নির্বাচন করুন।');const networkCode=$('adNetworkCode')?.value.trim()||'';const finalType=networkCode?'network':'direct';$('adType').value=finalType;if(finalType==='direct'&&placements.includes('popup'))throw new Error('পপআপ/পপআন্ডার স্থানে HTML/JavaScript কোড দিন।');const payload={advertiser_name:$('adAdvertiser').value.trim(),title:$('adTitle').value.trim(),ad_type:finalType,placement:placements.join(','),image_url:finalType==='network'?null:(adImage||null),target_url:$('adTarget').value.trim()||null,embed_code:JSON.stringify({network_code:networkCode,animation:$('adAnimation').checked,animation_type:$('adAnimationType').value,slider:$('adSlider').checked,slider_interval:Number($('adSliderInterval').value||5000)}),start_at:new Date($('adStart').value).toISOString(),end_at:$('adEnd').value?new Date($('adEnd').value).toISOString():null,price:Number($('adPrice').value||0),payment_status:$('adPayment').value,status:$('adStatus').value,article_id:$('adArticle').value?Number($('adArticle').value):null,updated_at:new Date().toISOString()};if(placements.includes('article')&&!payload.article_id)throw Error('নির্দিষ্ট সংবাদ বিজ্ঞাপনের জন্য সংবাদ নির্বাচন/আইডি দিন।');if(payload.end_at&&payload.end_at<=payload.start_at)throw Error('শেষের সময় শুরুর সময়ের পরে দিন।');if(finalType==='direct'&&!payload.image_url)throw Error('সরাসরি বিজ্ঞাপনের ছবি বা মিডিয়া URL দিন।');if(payload.status==='active'&&!confirm('বিজ্ঞাপনদাতা, বিজ্ঞাপনের কোড/মিডিয়া এবং গন্তব্য লিংক যাচাই করেছেন? অনুমোদন করে প্রকাশ করবেন?'))return;const r=id?await db.from('ad_campaigns').update(payload).eq('id',id):await db.from('ad_campaigns').insert(payload);if(r.error)throw r.error;resetAd();say('adMessage','বিজ্ঞাপন সংরক্ষিত হয়েছে।');await loadAds()}catch(err){say('adMessage','ব্যর্থ: '+err.message,true)}});
