async function loadStaff(){const box=$('staffList');if(!box||currentRole!=='admin')return;const {data,error}=await db.from('admin_users').select('user_id,role,created_at').eq('role','editor').order('created_at');if(error){box.innerHTML='<p>'+esc(error.message)+'</p>';return}box.innerHTML=(data||[]).map((u,i)=>'<div class="side-card"><b>এডিটর '+(i+1)+'</b><p><small>'+esc(u.user_id)+'</small></p><button class="btn btn-red" data-remove-editor="'+esc(u.user_id)+'">এডিটর সরান</button></div>').join('')||'<p class="muted">এখনো কোনো এডিটর যোগ করা হয়নি।</p>';$('editorSlots').textContent=(data||[]).length+' / 2 এডিটর স্লট ব্যবহৃত';box.querySelectorAll('[data-remove-editor]').forEach(b=>b.onclick=()=>removeEditor(b.dataset.removeEditor))}
$('staffForm').onsubmit=async e=>{e.preventDefault();if(currentRole!=='admin')return;const userId=$('editorUserId').value.trim();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId)){say('staffMessage','সঠিক Supabase Auth User UID দিন।',true);return}const {error}=await db.from('admin_users').insert({user_id:userId,role:'editor'});if(error){say('staffMessage','যোগ করা যায়নি: '+error.message,true);return}$('editorUserId').value='';say('staffMessage','এডিটর যোগ হয়েছে।');await loadStaff()};
async function removeEditor(userId){if(currentRole!=='admin'||!confirm('এই এডিটরের অনুমতি সরিয়ে দেবেন?'))return;const {error}=await db.from('admin_users').delete().eq('user_id',userId).eq('role','editor');if(error){toast('সরানো যায়নি: '+error.message);return}toast('এডিটর অনুমতি সরানো হয়েছে');await loadStaff()}
async function loadCommentsAdmin(){const box=$('adminComments');if(!box)return;const {data,error}=await db.from('article_comments').select('id,article_id,name,body,status,created_at,articles(title)').order('created_at',{ascending:false}).limit(300);if(error){box.innerHTML='<tr><td colspan="4">'+esc(error.message)+'</td></tr>';return}box.innerHTML=(data||[]).map(x=>'<tr><td><b>'+esc(x.articles?.title||('সংবাদ #'+x.article_id))+'</b><p>'+esc(x.body)+'</p><small>'+new Date(x.created_at).toLocaleString('bn-BD')+'</small></td><td>'+esc(x.name)+'</td><td>'+esc(x.status==='approved'?'প্রকাশিত':x.status==='rejected'?'বাতিল':'অপেক্ষমাণ')+'</td><td>'+(x.status!=='approved'?'<button class="btn" data-approve-comment="'+x.id+'">প্রকাশ</button> ':'')+(x.status!=='rejected'?'<button class="btn btn-light" data-reject-comment="'+x.id+'">বাতিল</button> ':'')+'<button class="btn btn-red" data-delete-comment="'+x.id+'">মুছুন</button></td></tr>').join('')||'<tr><td colspan="4">এখনো কোনো মন্তব্য নেই।</td></tr>';box.querySelectorAll('[data-approve-comment]').forEach(b=>b.onclick=()=>moderateComment(b.dataset.approveComment,'approved'));box.querySelectorAll('[data-reject-comment]').forEach(b=>b.onclick=()=>moderateComment(b.dataset.rejectComment,'rejected'));box.querySelectorAll('[data-delete-comment]').forEach(b=>b.onclick=()=>deleteComment(b.dataset.deleteComment))}
