async function uploadImage(file,folder){if(!file)return null;if(!file.type.startsWith('image/'))throw new Error('শুধু ছবির ফাইল আপলোড করা যাবে।');if(file.size>10*1024*1024)throw new Error('ছবির আকার ১০ MB-এর বেশি হতে পারবে না।');const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]/g,'-').slice(-80)||'image';const path=folder+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+safe;const {error}=await db.storage.from('dristipat-media').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(error)throw error;return db.storage.from('dristipat-media').getPublicUrl(path).data.publicUrl}
async function uploadVideo(file,folder){if(!file)return null;if(!['video/mp4','video/webm','video/ogg'].includes(file.type))throw new Error('শুধু MP4, WebM বা OGG ভিডিও আপলোড করা যাবে।');if(file.size>50*1024*1024)throw new Error('ভিডিওর আকার ৫০ MB-এর বেশি হতে পারবে না।');const safe=file.name.toLowerCase().replace(/[^a-z0-9._-]/g,'-').slice(-80)||'video.mp4';const path=folder+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+safe;const {error}=await db.storage.from('dristipat-media').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(error)throw error;return db.storage.from('dristipat-media').getPublicUrl(path).data.publicUrl}
function preview(file,inputId,previewId){if(!file){$(previewId).classList.add('hidden');return}$(previewId).src=URL.createObjectURL(file);$(previewId).classList.remove('hidden')}
