async function loadCategories(){const {data,error}=await db.from('categories').select('*').order('name');if(error){toast('ক্যাটেগরি লোড হয়নি: '+error.message);return}categories=data||[];$('postCategory').innerHTML=categories.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('');$('categoryList').innerHTML=categories.map(c=>'<span class="category-chip">'+esc(c.name)+' <button data-del-cat="'+c.id+'" aria-label="মুছুন">×</button></span>').join('');document.querySelectorAll('[data-del-cat]').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.delCat))}
async function loadVideos(){const box=$('adminVideos');if(!box)return;const {data,error}=await db.from('articles').select('id,title,status,video_url,created_at').not('video_url','is',null).neq('video_url','').order('created_at',{ascending:false}).limit(300);if(error){box.innerHTML='<tr><td colspan="4">'+esc(error.message)+'</td></tr>';return}box.innerHTML=(data||[]).map(v=>'<tr><td><b>'+esc(v.title)+'</b></td><td>'+(v.status==='published'?'প্রকাশিত':'খসড়া')+'</td><td><a href="'+esc(v.video_url)+'" target="_blank" rel="noopener noreferrer">ভিডিও খুলুন</a></td><td><button class="btn" data-video-edit="'+v.id+'">সংবাদ সম্পাদনা</button></td></tr>').join('')||'<tr><td colspan="4">এখনো কোনো সংবাদে ভিডিও যুক্ত করা হয়নি।</td></tr>';box.querySelectorAll('[data-video-edit]').forEach(b=>b.onclick=()=>editPost(b.dataset.videoEdit))} $('refreshVideos')?.addEventListener('click',loadVideos);async function loadPosts(){const {data,error}=await db.from('articles').select('id,title,status,created_at,slug,published_at,category_id,excerpt,summary,body,image_url,video_url,author,featured,breaking,is_breaking,views,ad_slots').order('created_at',{ascending:false}).limit(300);if(error){$('adminPosts').innerHTML='<tr><td colspan="4">'+esc(error.message)+'</td></tr>';return}posts=data||[];$('adminPosts').innerHTML=posts.map(p=>'<tr><td><b>'+esc(p.title)+'</b><br><small>'+(p.featured?'★ প্রধান ':'')+' · পঠিত: '+Number(p.views||0).toLocaleString('bn-BD')+'</small></td><td>'+(p.status==='published'?'প্রকাশিত':'খসড়া')+'</td><td>'+new Date(p.created_at).toLocaleDateString('bn-BD')+'</td><td><button class="btn" data-edit="'+p.id+'">সম্পাদনা</button> <button class="btn btn-red" data-delete="'+p.id+'">মুছুন</button></td></tr>').join('')||'<tr><td colspan="4">কোনো সংবাদ নেই।</td></tr>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editPost(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deletePost(b.dataset.delete))}
async function loadAdInventory(){if(currentRole!=='admin')return;const summary=['adInventoryTotal','adInventoryActive','adInventoryInactive'];summary.forEach(id=>{if($(id))$(id).textContent='লোড হচ্ছে…'});const inventory=$('adInventoryRows'),placementsBox=$('adPlacementStatusRows');if(inventory)inventory.innerHTML='<tr><td colspan="5">লোড হচ্ছে…</td></tr>';const [settingsRes,campaignRes,articleRes]=await Promise.all([db.from('site_settings').select('value').eq('key','ads').maybeSingle(),db.from('ad_campaigns').select('*').order('created_at',{ascending:false}).limit(500),db.from('articles').select('id,title,status,published_at,ad_slots').order('created_at',{ascending:false}).limit(1000)]);const err=settingsRes.error||campaignRes.error||articleRes.error;if(err){if(inventory)inventory.innerHTML='<tr><td colspan="5">বিজ্ঞাপন হিসাব লোড হয়নি: '+esc(err.message)+'</td></tr>';if(placementsBox)placementsBox.innerHTML='<tr><td colspan="4">অবস্থান যাচাই করা যায়নি।</td></tr>';summary.forEach(id=>{if($(id))$(id).textContent='—'});return}const globalAds=settingsRes.data?.value||{},campaigns=campaignRes.data||[],articles=articleRes.data||[],now=Date.now(),names={header:'হেডার',top:'হোমপেজ ব্যানার',important_links:'গুরুত্বপূর্ণ লিংকের উপরে',side:'সাইডবার',side_tall:'সাইডবারের লম্বা অংশ',feed:'সংবাদ ফিড',bottom:'ফুটার',article:'নির্দিষ্ট সংবাদ',popup:'নেটওয়ার্ক / পপআপ'},rows=[],placeState={};Object.keys(names).forEach(k=>placeState[k]={direct:false,campaign:false});const codeType=v=>{const value=String(v||'').trim().toLowerCase();return value.startsWith('https://')||value.startsWith('http://')?'Script URL':'HTML / JavaScript'};const add=(r)=>rows.push(r);for(const k of ['header','top','important_links','side','bottom']){const code=String(globalAds[k]||'').trim();if(!code)continue;const active=globalAds.enabled===true;add({name:names[k]+' — সাইট সেটিংস',type:codeType(code),place:k,content:'কোড সংরক্ষিত',active,source:'সাইটের সরাসরি কোড'});if(active)placeState[k].direct=true}campaigns.forEach(a=>{const placeKeys=String(a.placement||'').split(',').map(x=>x.trim()).filter(Boolean);let cfg={};try{cfg=JSON.parse(a.embed_code||'{}')}catch{}const hasContent=a.ad_type==='network'?!!String(cfg.network_code||'').trim():!!String(a.image_url||'').trim();const start=a.start_at?new Date(a.start_at).getTime():0,end=a.end_at?new Date(a.end_at).getTime():Infinity;const active=a.status==='active'&&start<=now&&end>now&&globalAds.enabled===true&&hasContent;const status=a.status!=='active'?'স্থগিত / খসড়া':start>now?'নির্ধারিত':end<=now?'মেয়াদ শেষ':!globalAds.enabled?'সাইটের বিজ্ঞাপন সুইচ বন্ধ':!hasContent?'কোড / মিডিয়া নেই':'চালু';const label=placeKeys.map(k=>names[k]||k).join(', ')||'স্থান নির্ধারিত নয়';add({name:(a.advertiser_name||'বিজ্ঞাপনদাতা')+' — '+(a.title||'শিরোনাম নেই'),type:a.ad_type==='network'?'নেটওয়ার্ক কোড':'সরাসরি ব্যানার / মিডিয়া',place:label,content:hasContent?(a.ad_type==='network'?codeType(cfg.network_code):'মিডিয়া'+(a.target_url?' ও ক্লিক লিংক':'')):'কোড / মিডিয়া নেই',active,status,source:'বিজ্ঞাপন ক্যাম্পেইন'});placeKeys.forEach(k=>{if(active&&placeState[k])placeState[k].campaign=true})});const positions={after_intro:'শুরুর অনুচ্ছেদের পরে',middle:'সংবাদের মাঝখানে',after_paragraph:'নির্দিষ্ট অনুচ্ছেদের পরে',end:'সংবাদের শেষে'};const kinds={media:'ছবি / ভিডিও',link:'সরাসরি লিংক',code:'HTML / JavaScript',code_auto:'HTML / JavaScript / Script URL'};articles.forEach(a=>(Array.isArray(a.ad_slots)?a.ad_slots:[]).forEach((s,i)=>{const live=a.status==='published'&&(!a.published_at||new Date(a.published_at).getTime()<=now);const hasContent=s.kind==='media'?!!String(s.media_url||'').trim():s.kind==='link'?!!String(s.target_url||'').trim():!!String(s.html_code||'').trim();const active=live&&hasContent;const status=!live?(a.status==='published'?'প্রকাশের সময় হয়নি':'খসড়া — লাইভ নয়'):!hasContent?'কোড / মিডিয়া নেই':'প্রকাশিত সংবাদে চালু';add({name:(a.title||'সংবাদ')+' — বিজ্ঞাপন '+(i+1),type:kinds[s.kind]||s.kind||'বিজ্ঞাপন',place:'নির্দিষ্ট সংবাদ: '+(positions[s.position]||s.position||'সংবাদের ভেতরে'),content:hasContent?(s.kind==='media'?'মিডিয়া সংরক্ষিত':s.kind==='link'?'লিংক সংরক্ষিত':codeType(s.html_code)):'কোড / মিডিয়া নেই',active,status,source:'সংবাদে যুক্ত বিজ্ঞাপন'});if(active)placeState.article.campaign=true}));const activeCount=rows.filter(x=>x.active).length;if($('adInventoryTotal'))$('adInventoryTotal').textContent=rows.length.toLocaleString('bn-BD');if($('adInventoryActive'))$('adInventoryActive').textContent=activeCount.toLocaleString('bn-BD');if($('adInventoryInactive'))$('adInventoryInactive').textContent=(rows.length-activeCount).toLocaleString('bn-BD');if(inventory)inventory.innerHTML=rows.map(r=>'<tr><td><b>'+esc(r.name)+'</b><br><small>'+esc(r.source)+'</small></td><td>'+esc(r.type)+'</td><td>'+esc(r.place)+'</td><td>'+esc(r.content)+'</td><td><strong style="color:'+(r.active?'#138444':'#b7791f')+'">'+esc(r.status|| (r.active?'চালু':'বন্ধ'))+'</strong></td></tr>').join('')||'<tr><td colspan="5">এখনো কোনো বিজ্ঞাপন এন্ট্রি নেই।</td></tr>';const allPlaces=Object.keys(names);if(placementsBox)placementsBox.innerHTML=allPlaces.map(k=>{const direct=placeState[k].direct,campaign=placeState[k].campaign,active=direct||campaign;return '<tr><td>'+esc(names[k])+'</td><td>'+(direct?'চালু':'বন্ধ / কোড নেই')+'</td><td>'+(campaign?'চালু':'বন্ধ / বিজ্ঞাপন নেই')+'</td><td><strong style="color:'+(active?'#138444':'#b51f2b')+'">'+(active?'বিজ্ঞাপন চালু':'এখন বিজ্ঞাপন চালু নেই')+'</strong></td></tr>'}).join('');const generalBox=$('generalAdRows');if(generalBox){const slots=['header','top','side','bottom'];generalBox.innerHTML=slots.map(k=>{const code=String(globalAds[k]||'').trim();return '<tr><td>'+esc(names[k])+'</td><td>'+(code?esc(codeType(code))+' কোড সংরক্ষিত':'কোড নেই')+'</td><td>'+(globalAds.enabled===true&&code?'চালু':'বন্ধ')+'</td></tr>'}).join('')}const articleBox=$('articleAdRows');if(articleBox){const articleRows=rows.filter(r=>r.source==='সংবাদে যুক্ত বিজ্ঞাপন');articleBox.innerHTML=articleRows.map(r=>'<tr><td><b>'+esc(r.name)+'</b></td><td>'+esc(r.type)+'</td><td>'+esc(r.place)+'</td><td>'+esc(r.status)+'</td></tr>').join('')||'<tr><td colspan="4">এখনো কোনো সংবাদে বিজ্ঞাপন যুক্ত নেই।</td></tr>'}}async function loadGeneralAdInventory(){return loadAdInventory()}async function loadArticleAdInventory(){return loadAdInventory()}
$('refreshGeneralAdInventory')?.addEventListener('click',loadAdInventory);$('refreshArticleAds')?.addEventListener('click',loadAdInventory);$('refreshAdInventory')?.addEventListener('click',loadAdInventory);
function articleAdRow(s={}){const b=document.createElement('div');b.className='article-ad-row';b.innerHTML='<div class="article-ad-row-head"><b>বিজ্ঞাপন</b><button type="button" class="btn btn-red remove-article-ad">বাদ দিন</button></div><div class="article-ad-fields"><label>ধরন<select class="kind"><option value="media">ছবি/ভিডিও</option><option value="link">শুধু লিংক</option><option value="code">HTML / JavaScript</option></select></label><label>অবস্থান<select class="position"><option value="after_intro">শুরুর অনুচ্ছেদের পরে</option><option value="middle">মাঝখানে</option><option value="after_paragraph">নির্দিষ্ট অনুচ্ছেদের পরে</option><option value="end">সংবাদের শেষে</option></select></label><label>অনুচ্ছেদ নম্বর<input class="paragraph" type="number" min="1" value="3"></label><label>সাইজ<select class="size"><option value="small">ছোট 300×100</option><option value="medium">মাঝারি 300×250</option><option value="large">বড় 728×250</option><option value="wide">পূর্ণ প্রস্থ 970×250</option><option value="tall">লম্বা 300×600</option><option value="custom">কাস্টম</option></select></label><label>কাস্টম প্রস্থ px<input class="width" type="number" min="100" max="1200"></label><label>কাস্টম উচ্চতা px<input class="height" type="number" min="60" max="1200"></label><label>অ্যানিমেশন<select class="animation"><option value="none">বন্ধ</option><option>fade</option><option>slide</option><option>dance</option><option>zoom</option><option>pulse</option><option>shake</option><option>flip</option><option>rotate</option></select></label><label>স্লাইড সময়<select class="interval"><option value="1000">১ সেকেন্ড</option><option value="2000">২ সেকেন্ড</option><option value="3000">৩ সেকেন্ড</option><option value="4000">৪ সেকেন্ড</option><option value="5000">৫ সেকেন্ড</option></select></label><label class="wide">ছবি/ভিডিও ফাইল<input class="file" type="file" accept="image/*,video/mp4,video/webm,video/ogg"></label><label class="wide">মিডিয়া URL<input class="media" type="url" placeholder="https://...jpg / .mp4"></label><label class="wide">গন্তব্য লিংক<input class="target" type="url" placeholder="https://..."></label><label class="wide">লিংকের লেখা<input class="linktext" maxlength="140" placeholder="বিস্তারিত জানতে ক্লিক করুন"></label><label class="wide">HTML / JavaScript কোড<textarea class="htmlcode" rows="6" placeholder="নিজের বিজ্ঞাপনদাতার দেওয়া HTML / JavaScript কোড এখানে দিন"></textarea><small>কোডটি আলাদা sandbox iframe-এ চলবে; সাইটের Admin বা মূল পেজের স্ক্রিপ্টে সরাসরি প্রবেশ পাবে না।</small></label></div>';for(const [k,v] of Object.entries({kind:s.kind||'media',position:s.position||'after_intro',paragraph:s.paragraph||3,size:s.size||'medium',width:s.width||'',height:s.height||'',animation:s.animation||'none',interval:s.interval||3000,media:s.media_url||'',target:s.target_url||'',linktext:s.link_text||'',htmlcode:s.html_code||''}))b.querySelector('.'+k).value=v;b.querySelector('.remove-article-ad').onclick=()=>b.remove();const codeField=b.querySelector('.htmlcode'),kindField=b.querySelector('.kind');codeField.addEventListener('input',()=>{if(codeField.value.trim())kindField.value='code'});return b}
function setArticleAdRows(rows=[]){const root=$('articleAdSlots');if(root){root.replaceChildren();const configurable=(rows||[]).filter(s=>s.kind!=='code_auto');const enabled=$('articleAdOptionsEnabled');if(enabled){enabled.checked=configurable.length>0;$('articleAdOptions')?.classList.toggle('hidden',!enabled.checked)}configurable.forEach(s=>root.appendChild(articleAdRow(s)));const code=(rows||[]).find(s=>s.kind==='code_auto');if($('postArticleAdCode'))$('postArticleAdCode').value=code?.html_code||'';if($('postArticleAdCodePosition'))$('postArticleAdCodePosition').value=code?.position||'after_intro'}}
function readArticleAdRows(){return [...document.querySelectorAll('#articleAdSlots .article-ad-row')].map(b=>({kind:b.querySelector('.htmlcode').value.trim()?'code':b.querySelector('.kind').value,position:b.querySelector('.position').value,paragraph:+b.querySelector('.paragraph').value||3,size:b.querySelector('.size').value,width:+b.querySelector('.width').value||null,height:+b.querySelector('.height').value||null,animation:b.querySelector('.animation').value,interval:+b.querySelector('.interval').value,media_url:b.querySelector('.media').value.trim(),target_url:b.querySelector('.target').value.trim(),link_text:b.querySelector('.linktext').value.trim(),html_code:b.querySelector('.htmlcode').value,file:b.querySelector('.file').files[0]||null}))}
$('articleAdOptionsEnabled')?.addEventListener('change',e=>$('articleAdOptions')?.classList.toggle('hidden',!e.target.checked));
$('addArticleAd')?.addEventListener('click',()=> $('articleAdSlots').appendChild(articleAdRow()));
function editPost(id){const p=posts.find(x=>String(x.id)===String(id));if(!p)return;$('postId').value=p.id;$('postTitle').value=p.title;$('postCategory').value=p.category_id||'';$('postExcerpt').value=p.excerpt||p.summary||'';$('postBody').value=p.body||'';setArticleAdRows(Array.isArray(p.ad_slots)?p.ad_slots:[]);$('postVideoUrl').value=p.video_url||'';$('postVideoFile').value='';if(p.video_url&&/\.(mp4|webm|ogg)(\?.*)?$/i.test(p.video_url)){$('postVideoPreview').src=p.video_url;$('postVideoPreview').classList.remove('hidden')}else{$('postVideoPreview').classList.add('hidden');$('postVideoPreview').removeAttribute('src')}$('postImage').value=p.image_url||'';$('postImageUrl').value=p.image_url||'';$('postImageFile').value='';if(p.image_url){$('postImagePreview').src=p.image_url;$('postImagePreview').classList.remove('hidden')}else $('postImagePreview').classList.add('hidden');$('postAuthor').value=p.author||'দৃষ্টিপাতBD';$('postFeatured').checked=!!p.featured;$('postStatus').value=p.status;$('postSchedule').value=p.published_at?(()=>{const d=new Date(p.published_at);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)})():'';$('editorTitle').textContent='সংবাদ সম্পাদনা';document.querySelector('[data-tab="posts"]').click();window.scrollTo({top:0,behavior:'smooth'})}
function resetPost(){$('postForm').reset();setArticleAdRows([]);$('postId').value='';$('postImage').value='';$('postImageUrl').value='';$('postVideoUrl').value='';$('postVideoFile').value='';$('postVideoPreview').classList.add('hidden');$('postVideoPreview').removeAttribute('src');$('postImagePreview').classList.add('hidden');$('postSchedule').value='';$('postAuthor').value='দৃষ্টিপাতBD';$('editorTitle').textContent='নতুন সংবাদ লিখুন';say('postMessage','')}
$('resetPost').onclick=resetPost;
$('postForm').onsubmit=async e=>{e.preventDefault();const id=$('postId').value;const old=posts.find(p=>String(p.id)===String(id));const status=$('postStatus').value;const title=$('postTitle').value.trim();const scheduleValue=$('postSchedule').value;say('postMessage','সংরক্ষণ হচ্ছে...');try{let imageUrl=$('postImageUrl').value.trim()||$('postImage').value.trim();const file=$('postImageFile').files[0];if(file)imageUrl=await uploadImage(file,'articles');const videoFile=$('postVideoFile').files[0];const videoUrl=videoFile?await uploadVideo(videoFile,'articles'):($('postVideoUrl').value.trim()||null);const adRows=$('articleAdOptionsEnabled')?.checked?readArticleAdRows():[],adSlots=[];for(const row of adRows){if(row.kind==='code'){if(!row.html_code.trim())throw new Error('HTML / JavaScript বিজ্ঞাপন কোড দিন।')}else if(row.kind==='media'){if(row.file)row.media_url=await (row.file.type.startsWith('video/')?uploadVideo(row.file,'ads'):uploadImage(row.file,'ads'));if(!row.media_url)throw new Error('বিজ্ঞাপনের মিডিয়া ফাইল বা URL দিন।')}else if(row.kind==='link'&&!row.target_url)throw new Error('লিংক বিজ্ঞাপনের গন্তব্য URL দিন।');if(row.size==='custom'&&(!row.width||!row.height))throw new Error('কাস্টম সাইজের প্রস্থ ও উচ্চতা দিন।');delete row.file;adSlots.push(row)}const standaloneCode=$('postArticleAdCode')?.value.trim()||'';if(standaloneCode)adSlots.push({kind:'code_auto',position:$('postArticleAdCodePosition')?.value||'after_intro',html_code:standaloneCode,size:'auto',animation:'none'});const payload={title,slug:old?.slug||slugify(title),ad_slots:adSlots,category_id:$('postCategory').value||null,excerpt:$('postExcerpt').value.trim(),summary:$('postExcerpt').value.trim(),body:$('postBody').value.trim(),image_url:imageUrl,video_url:videoUrl,author:$('postAuthor').value.trim()||'দৃষ্টিপাতBD',featured:$('postFeatured').checked,breaking:false,is_breaking:false,status,published_at:status==='published'?(scheduleValue?new Date(scheduleValue).toISOString():(old?.published_at&&new Date(old.published_at)<=new Date()?old.published_at:new Date().toISOString())):null,updated_at:new Date().toISOString()};const res=id?await db.from('articles').update(payload).eq('id',id):await db.from('articles').insert(payload);if(res.error)throw res.error;say('postMessage','সংবাদ সংরক্ষিত হয়েছে।');resetPost();await Promise.all([loadPosts(),loadVideos()])}catch(err){say('postMessage','সংরক্ষণ ব্যর্থ: '+(err.message||err),true)}};
async function deletePost(id){if(!confirm('এই সংবাদটি স্থায়ীভাবে মুছে ফেলবেন?'))return;const {error}=await db.from('articles').delete().eq('id',id);if(error){toast(error.message);return}toast('সংবাদ মুছে ফেলা হয়েছে');await loadPosts()}
$('categoryForm').onsubmit=async e=>{e.preventDefault();const name=$('categoryName').value.trim();const {error}=await db.from('categories').insert({name,slug:slugify(name).replace(/-[a-z0-9]{5}$/,'')});if(error){toast('ক্যাটেগরি যোগ হয়নি: '+error.message);return}$('categoryName').value='';await loadCategories();toast('ক্যাটেগরি যোগ হয়েছে')};
async function deleteCategory(id){if(!confirm('ক্যাটেগরি মুছবেন?'))return;const {error}=await db.from('categories').delete().eq('id',id);if(error){toast(error.message);return}await loadCategories();toast('ক্যাটেগরি মুছে ফেলা হয়েছে')}
async function loadSettings(){const {data,error}=await db.from('site_settings').select('key,value');if(error){toast('সেটিংস লোড হয়নি: '+error.message);say('breakingMessage','সেটিংস লোড হয়নি: '+error.message,true);return}settings={};(data||[]).forEach(x=>settings[x.key]=x.value);const g=settings.general||{},a=settings.ads||{};$('setTagline').value=g.tagline||'';$('setEditorCredit').value=g.editor_credit||'ভারপ্রাপ্ত সম্পাদক : আবুল কাশেম বোরহান';$('setLogo').value=g.logo||'';$('setFacebook').value=g.facebook||'';$('setYoutube').value=g.youtube||'';$('setEmail').value=g.email||'';$('setMobile').value=g.mobile||'00966573424966';$('setAboutTitle').value=g.page_about_title||'আমাদের সম্পর্কে';$('setAboutContent').value=g.page_about_content||"দৃষ্টিপাতBD একটি অনলাইন সংবাদমাধ্যম। সত্য, নিরপেক্ষতা ও জনস্বার্থকে সামনে রেখে পাঠকের কাছে সংবাদ ও তথ্য পৌঁছে দেওয়াই আমাদের লক্ষ্য।\\n\\nআমাদের লক্ষ্য\\nদেশ-বিদেশের গুরুত্বপূর্ণ ঘটনা, জনজীবন, সমাজ, শিক্ষা, অর্থনীতি, সংস্কৃতি ও অন্যান্য প্রাসঙ্গিক বিষয়ে পাঠককে তথ্যসমৃদ্ধ সংবাদ দেওয়ার চেষ্টা করি। সংবাদ প্রকাশের ক্ষেত্রে তথ্যের যথার্থতা, প্রাসঙ্গিকতা এবং পাঠকের স্বার্থকে গুরুত্ব দেওয়া হয়।\\n\\nসংবাদ যাচাই ও সংশোধন\\nসংবাদ প্রকাশের আগে প্রাপ্ত তথ্য ও সূত্র যাচাই করার চেষ্টা করা হয়। কোনো প্রকাশিত প্রতিবেদনে ভুল বা সংশোধনযোগ্য তথ্য চোখে পড়লে পাঠকদের অনুরোধ, সংশ্লিষ্ট তথ্য এবং নির্ভরযোগ্য সূত্র পর্যালোচনা করে প্রয়োজনীয় সংশোধনের বিষয়টি বিবেচনা করা হবে।\\n\\nসম্পাদকীয় দায়িত্ব\\nভারপ্রাপ্ত সম্পাদক: আবুল কাশেম বোরহান\\nইমেইল: abulkasam117@gmail.com\\n\\nযোগাযোগ\\nপাঠকের মতামত, তথ্য সংশোধন, সংবাদ-সংক্রান্ত যোগাযোগ বা অন্যান্য প্রশ্নের জন্য যোগাযোগ পাতায় দেওয়া মাধ্যম ব্যবহার করুন।";$('setContactTitle').value=g.page_contact_title||'যোগাযোগ করুন';$('setContactContent').value=g.page_contact_content||"সংবাদ-সংক্রান্ত তথ্য, সংশোধনের অনুরোধ, পাঠকের মতামত, বিজ্ঞাপন এবং অন্যান্য বিষয়ে দৃষ্টিপাতBD-এর সঙ্গে যোগাযোগ করুন।\\n\\nঠিকানা: পিংসিটি সেন্টার, পুরানা পল্টন, ঢাকা–১০০০, বাংলাদেশ\\n\\nভারপ্রাপ্ত সম্পাদক: আবুল কাশেম বোরহান\\nসম্পাদকীয় ইমেইল: abulkasam117@gmail.com\\n\\nপ্রতিবেদন সংশোধন বা তথ্যের সত্যতা সম্পর্কে জানাতে ইমেইলে সংশ্লিষ্ট প্রতিবেদনের লিংক এবং যাচাইযোগ্য তথ্য উল্লেখ করুন।";$('setPrivacyTitle').value=g.page_privacy_title||'গোপনীয়তা নীতি';$('setPrivacyContent').value=g.page_privacy_content||"সর্বশেষ হালনাগাদ: ২২ নভেম্বর ২০২৬\\n\\nদৃষ্টিপাতBD-তে পাঠকের গোপনীয়তাকে গুরুত্ব দেওয়া হয়। এই নীতিতে ব্যাখ্যা করা হয়েছে যে ওয়েবসাইট ব্যবহার করার সময় কী ধরনের তথ্য প্রক্রিয়াকৃত হতে পারে এবং তা কীভাবে ব্যবহৃত হতে পারে।\\n\\n১. আপনি যে তথ্য দেন\\nআপনি ইমেইল, ফোন বা WhatsApp-এর মাধ্যমে যোগাযোগ করলে আপনার পাঠানো নাম, যোগাযোগের তথ্য ও বার্তার বিষয়বস্তু আমরা উত্তর দেওয়া, অনুরোধ পর্যালোচনা বা সংশ্লিষ্ট যোগাযোগ পরিচালনার জন্য ব্যবহার করতে পারি। প্রকাশিত সংবাদে মন্তব্যের সুবিধা ব্যবহার করলে আপনার দেওয়া নাম ও মন্তব্য সংরক্ষিত এবং যাচাইয়ের পর প্রকাশিত হতে পারে।\\n\\n২. প্রযুক্তিগত তথ্য ও কুকি\\nওয়েবসাইট পরিচালনা, নিরাপত্তা, কর্মক্ষমতা ও ব্যবহার বোঝার জন্য হোস্টিং বা সংশ্লিষ্ট প্রযুক্তিগত সেবা লগ, ডিভাইস/ব্রাউজারের তথ্য, IP ঠিকানা বা কুকির মতো তথ্য প্রক্রিয়াকরণ করতে পারে। সাইটের সক্রিয় ফিচার ও তৃতীয় পক্ষের সেবার ওপর নির্ভর করে তথ্যের ধরন ভিন্ন হতে পারে।\\n\\n৩. বিজ্ঞাপন ও তৃতীয় পক্ষ\\nতৃতীয় পক্ষের বিজ্ঞাপন সেবা বিজ্ঞাপন দেখানো, পরিমাপ করা বা প্রাসঙ্গিকতা নির্ধারণের জন্য কুকি বা অনুরূপ প্রযুক্তি ব্যবহার করতে পারে। বিজ্ঞাপন সেবা চালু হলে সংশ্লিষ্ট প্রদানকারীর নীতি এবং প্রযোজ্য সম্মতি/গোপনীয়তা সংক্রান্ত নিয়ম অনুসরণ করা হবে।\\n\\n৪. তথ্য ব্যবহার ও শেয়ার\\nযোগাযোগের উত্তর দেওয়া, পাঠকের মন্তব্য পরিচালনা, সাইটের নিরাপত্তা ও কার্যক্রম বজায় রাখা এবং প্রযোজ্য আইন মেনে চলার প্রয়োজনে তথ্য ব্যবহার করা হতে পারে।\\n\\n৫. বহিঃস্থ লিংক\\nসাইটে অন্য ওয়েবসাইটের লিংক থাকতে পারে। সেসব সাইটের বিষয়বস্তু, নিরাপত্তা বা গোপনীয়তা নীতির জন্য সংশ্লিষ্ট সাইটের নিজস্ব শর্ত প্রযোজ্য।\\n\\n৬. শিশুদের গোপনীয়তা\\nএই ওয়েবসাইট বিশেষভাবে শিশুদের লক্ষ্য করে তৈরি নয়। অভিভাবকের অনুমতি ছাড়া শিশুদের ব্যক্তিগত তথ্য পাঠানো থেকে বিরত থাকার অনুরোধ করা হচ্ছে।\\n\\n৭. নীতির পরিবর্তন\\nসাইটের ফিচার, আইন বা সেবা পরিবর্তিত হলে এই নীতি হালনাগাদ করা হতে পারে।\\n\\n৮. যোগাযোগ\\nএই নীতি সম্পর্কে প্রশ্ন থাকলে যোগাযোগ পাতায় দেওয়া ইমেইল বা যোগাযোগ মাধ্যম ব্যবহার করুন।";$('setHeaderAd').value=a.header||'';$('setTopAd').value=a.top||'';$('setImportantLinksAd').value=a.important_links||'';$('setSideAd').value=a.side||'';$('setBottomAd').value=a.bottom||'';$('setAdNotes').value='';if($('adsEnabled'))$('adsEnabled').checked=a.enabled===true;let items=Array.isArray(g.breaking_items)?g.breaking_items:[];if(!items.length){const {data:oldNews,error:newsError}=await db.from('articles').select('id,title,breaking,is_breaking,published_at,created_at').eq('status','published').order('published_at',{ascending:false,nullsFirst:false}).limit(100);if(newsError){say('breakingMessage','আগের ব্রেকিং নিউজ লোড হয়নি: '+newsError.message,true)}else{const oldBreaking=(oldNews||[]).filter(x=>x.breaking===true||x.is_breaking===true);if(oldBreaking.length){items=oldBreaking.map(x=>x.title);say('breakingMessage','ডেটাবেসে থাকা '+items.length+'টি আগের ব্রেকিং নিউজ দেখানো হচ্ছে। সম্পাদনা করে সংরক্ষণ করুন।')}}}$('breakingItems').value=items.join('\n');$('breakingEnabled').checked=g.breaking_enabled!==false;if(g.logo){$('logoPreview').src=g.logo;$('logoPreview').classList.remove('hidden')}}
async function saveSetting(key,value){return await db.from('site_settings').upsert({key,value,updated_at:new Date().toISOString()},{onConflict:'key'})}
$('saveAdsEnabled')?.addEventListener('click',async()=>{if(currentRole!=='admin')return;const ads={...(settings.ads||{}),enabled:$('adsEnabled').checked,header:$('setHeaderAd').value.trim(),top:$('setTopAd').value.trim(),side:$('setSideAd').value.trim(),bottom:$('setBottomAd').value.trim(),important_links:$('setImportantLinksAd').value.trim(),notes:$('setAdNotes').value.trim()};const {error}=await saveSetting('ads',ads);if(error){say('adsGlobalMessage','সংরক্ষণ ব্যর্থ: '+error.message,true);return}settings.ads=ads;say('adsGlobalMessage',ads.enabled?'অনুমোদিত সরাসরি বিজ্ঞাপন প্রদর্শন চালু।':'সব বিজ্ঞাপন প্রদর্শন বন্ধ।');toast('বিজ্ঞাপন সেটিংস সংরক্ষিত')});
$('breakingForm').onsubmit=async e=>{e.preventDefault();say('breakingMessage','সংরক্ষণ হচ্ছে...');const general={...(settings.general||{}),breaking_items:$('breakingItems').value.split('\n').map(x=>x.trim()).filter(Boolean),breaking_enabled:$('breakingEnabled').checked};const {error}=await saveSetting('general',general);if(error){say('breakingMessage',error.message,true);return}settings.general=general;say('breakingMessage','ব্রেকিং নিউজ প্রকাশিত হয়েছে।');toast('ব্রেকিং নিউজ আপডেট হয়েছে')};
$('settingsForm').onsubmit=async e=>{e.preventDefault();say('settingsMessage','সেটিংস সংরক্ষণ হচ্ছে...');try{let logo=$('setLogo').value.trim();const file=$('setLogoFile').files[0];if(file)logo=await uploadImage(file,'logos');const general={...(settings.general||{}),tagline:$('setTagline').value.trim(),editor_credit:$('setEditorCredit').value.trim()||'ভারপ্রাপ্ত সম্পাদক : আবুল কাশেম বোরহান',logo,facebook:$('setFacebook').value.trim(),youtube:$('setYoutube').value.trim(),email:$('setEmail').value.trim(),mobile:$('setMobile').value.trim(),page_about_title:$('setAboutTitle').value.trim()||'আমাদের সম্পর্কে',page_about_content:$('setAboutContent').value,page_contact_title:$('setContactTitle').value.trim()||'যোগাযোগ করুন',page_contact_content:$('setContactContent').value,page_privacy_title:$('setPrivacyTitle').value.trim()||'গোপনীয়তা নীতি',page_privacy_content:$('setPrivacyContent').value};const ads={...(settings.ads||{}),enabled:settings.ads?.enabled===true,header:$('setHeaderAd').value.trim(),top:$('setTopAd').value.trim(),side:$('setSideAd').value.trim(),bottom:$('setBottomAd').value.trim(),important_links:$('setImportantLinksAd').value.trim(),notes:$('setAdNotes').value.trim()};let {error}=await saveSetting('general',general);if(!error)({error}=await saveSetting('ads',ads));if(error)throw error;settings.general=general;settings.ads=ads;say('settingsMessage','সেটিংস সংরক্ষিত হয়েছে।');toast('সেটিংস আপডেট হয়েছে')}catch(err){say('settingsMessage','সংরক্ষণ ব্যর্থ: '+(err.message||err),true)}};
